// Prepara los textos de los dos emails a partir del lead que envía el simulador.
const b = $input.first().json.body || {};
const esc = (s) => String(s == null ? '' : s).replace(/[&<>"']/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]));
const eur = (n) => (n == null ? '' : String(Math.round(n)).replace(/\B(?=(\d{3})+(?!\d))/g, '.') + ' €');
const LABEL = { encaja: 'Encaja', a_confirmar: 'A confirmar', no_encaja: 'No encaja', no_evaluable: 'Por revisar' };
const r = b.result || {}, c = b.contact || {}, a = b.answers || {}, t = b.tracking || {};
const e = r.enisa || {}, n = r.neotec || {};
const li = (arr) => '<ul>' + (arr || []).map((x) => '<li>' + esc(x) + '</li>').join('') + '</ul>';
const AGENDA_URL = 'https://andseed.com/contacto/'; // TODO: URL del calendario de llamadas

const reportHtml =
  '<h2>ENISA: ' + esc(LABEL[e.status] || e.status) + '</h2>' +
  (e.max_amount != null ? '<p><strong>Importe máximo orientativo: ' + eur(e.max_amount) + '</strong>' + (e.line ? ' (línea de referencia: ' + esc(e.line) + ')' : '') + '</p>' : '') +
  li(e.reason_texts) +
  '<h2>NEOTEC: ' + esc(LABEL[n.status] || n.status) + '</h2>' +
  '<p>Según los requisitos de la convocatoria ' + esc(n.convocatoria) + (n.closed ? ' (plazo cerrado)' : '') + '.</p>' +
  (n.max_aid != null ? '<p><strong>Ayuda de hasta ' + eur(n.max_aid) + '</strong></p>' : '') +
  li(n.reason_texts) +
  '<h2>Siguientes pasos</h2><ol>' + (r.next_steps || []).map((x) => '<li>' + esc(x) + '</li>').join('') + '</ol>' +
  '<p><em>Estimación orientativa. No garantiza la concesión de ninguna ayuda.</em></p>';

const htmlLead =
  '<div style="font-family:Arial,sans-serif;color:#0d1b4b;max-width:620px">' +
  '<p>Hola ' + esc((c.name || '').split(' ')[0]) + ',</p>' +
  '<p>Este es el informe completo que has desbloqueado en el simulador de financiación de Andseed.</p>' +
  reportHtml +
  '<p><a href="' + AGENDA_URL + '" style="background:#012060;color:#fff;padding:12px 22px;border-radius:99px;text-decoration:none">Agenda una llamada gratuita</a></p>' +
  '</div>';

const row = (k, v) => '<tr><td style="padding:4px 12px 4px 0"><strong>' + k + '</strong></td><td>' + esc(v) + '</td></tr>';
const htmlInternal =
  '<div style="font-family:Arial,sans-serif;color:#0d1b4b">' +
  '<h2>Nuevo lead del simulador ' + (b.qualified ? '(CUALIFICADO)' : '(no cualificado)') + ' · score ' + esc(b.score) + '</h2>' +
  '<table>' + row('Nombre', c.name) + row('Empresa', c.company) + row('Email', c.email) + row('Teléfono', c.phone) +
  row('Año constitución', a.anio_constitucion == null ? 'Sin constituir' : a.anio_constitucion) + row('Capital', a.capital_tramo) + row('Fondos propios', eur(a.fondos_propios)) +
  row('Tecnología', a.tecnologia) + row('Importe buscado', a.importe_tramo) + row('Ampliación de capital', a.ampliacion) +
  row('Fuente', [t.utm_source, t.utm_medium, t.utm_campaign].filter(Boolean).join(' / ')) + row('gclid', t.gclid) + row('Página', b.page_url) + '</table>' +
  reportHtml + '</div>';

return [{ json: {
  body: b,
  subjectInternal: (b.qualified ? '[CUALIFICADO] ' : '') + 'Nuevo lead simulador: ' + (c.company || c.name || ''),
  subjectLead: 'Tu informe de financiación ENISA y NEOTEC | Andseed',
  htmlInternal, htmlLead,
  leadEmail: c.email
} }];
